import{_ as e,o as l,c as d,a3 as s}from"./chunks/framework.DXf0zkj5.js";const f=JSON.parse('{"title":"Architecture Decision Records (ADR) Log","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/decisions.md","filePath":"system-design/decisions.md"}'),i={name:"system-design/decisions.md"};function n(a,t,r,o,c,g){return l(),d("div",null,[...t[0]||(t[0]=[s('<h1 id="architecture-decision-records-adr-log" tabindex="-1">Architecture Decision Records (ADR) Log <a class="header-anchor" href="#architecture-decision-records-adr-log" aria-label="Permalink to &quot;Architecture Decision Records (ADR) Log&quot;">​</a></h1><p>This table documents every major architectural design decision made in <code>17-cdn-caching-proxy</code>.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Decision ID</th><th style="text-align:left;">Decision Topic</th><th style="text-align:left;">Chosen Option</th><th style="text-align:left;">Alternatives Considered</th><th style="text-align:left;">Deciding Factors</th><th style="text-align:left;">Trade-off Accepted</th><th style="text-align:left;">Revisit When</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>ADR-001</strong></td><td style="text-align:left;">Core Runtime</td><td style="text-align:left;">Node.js Streams + TypeScript</td><td style="text-align:left;">Rust Hyper, Go net/http, Nginx C++</td><td style="text-align:left;">Unified TypeScript codebase with Next.js dashboard; rapid iteration on RFC 9111 logic.</td><td style="text-align:left;">Slightly higher memory baseline than pure C++ or Rust.</td><td style="text-align:left;">Single-core throughput exceeds 100k RPS.</td></tr><tr><td style="text-align:left;"><strong>ADR-002</strong></td><td style="text-align:left;">In-Memory Storage</td><td style="text-align:left;">Segmented Buffers (<code>MemoryStore</code>)</td><td style="text-align:left;">Redis 7, Memcached, SQLite</td><td style="text-align:left;">Eliminates 1ms network hop; delivers true sub-millisecond edge response times.</td><td style="text-align:left;">Cache memory is isolated per proxy instance.</td><td style="text-align:left;">Cluster exceeds 50 stateless proxy pods.</td></tr><tr><td style="text-align:left;"><strong>ADR-003</strong></td><td style="text-align:left;">Thundering Herd</td><td style="text-align:left;">In-Memory <code>RequestCoalescer</code></td><td style="text-align:left;">Redis Distributed Lock, RabbitMQ</td><td style="text-align:left;">Zero-latency coordination; instant stream fanout to all waiting sockets.</td><td style="text-align:left;">Leader socket failure requires follower re-election.</td><td style="text-align:left;">Multi-tier origin shield clustering required.</td></tr><tr><td style="text-align:left;"><strong>ADR-004</strong></td><td style="text-align:left;">Purge Strategy</td><td style="text-align:left;">Inverted Tag Index (<code>PurgeIndex</code>)</td><td style="text-align:left;">URL scanning, Regex scan</td><td style="text-align:left;">O(1) tag lookup allows invalidating 1,000 items in &lt; 5ms.</td><td style="text-align:left;">Tag index consumes additional RAM.</td><td style="text-align:left;">Unique tag cardinality exceeds 10,000,000.</td></tr><tr><td style="text-align:left;"><strong>ADR-005</strong></td><td style="text-align:left;">Compression Engine</td><td style="text-align:left;">Native Node.js <code>zlib</code></td><td style="text-align:left;">External Wasm codec, Origin compression</td><td style="text-align:left;">Zero external native bindings; streaming transforms with backpressure.</td><td style="text-align:left;">Brotli level 11 CPU intensive; capped at level 6.</td><td style="text-align:left;">Hardware compression accelerator cards available.</td></tr><tr><td style="text-align:left;"><strong>ADR-006</strong></td><td style="text-align:left;">Telemetry Protocol</td><td style="text-align:left;">Prometheus 0.0.4 Text Format</td><td style="text-align:left;">StatsD, InfluxDB, Custom JSON</td><td style="text-align:left;">Standard ecosystem compatibility with Prometheus and Grafana.</td><td style="text-align:left;">Pull-based scrape model requires HTTP endpoint.</td><td style="text-align:left;">Real-time push metrics needed at 100k nodes.</td></tr><tr><td style="text-align:left;"><strong>ADR-007</strong></td><td style="text-align:left;">Frontend Dashboard</td><td style="text-align:left;">Next.js 14 App Router + Recharts</td><td style="text-align:left;">Vite React SPA, Grafana dashboard</td><td style="text-align:left;">Self-contained, custom control UI with dynamic route and purge forms.</td><td style="text-align:left;">Node.js runtime needed for Next.js build.</td><td style="text-align:left;">Dedicated central multi-cluster UI built.</td></tr></tbody></table>',3)])])}const x=e(i,[["render",n]]);export{f as __pageData,x as default};
